#!/usr/bin/env bash
#
# verify-no-any.sh
#
# Verifies zero `any` type annotations in user-authored TypeScript code.
# Checks production (app/, components/, lib/, convex/) and test (tests/) files.
#
# Excludes:
#   - convex/_generated/ (auto-generated by Convex)
#   - node_modules/ and .next/ (third-party and build output)
#   - Variable names containing "any" (e.g., anyPdfEvidenceUsed)
#   - Test description strings containing "any" as an English word
#   - Comment-only lines
#
# Exit codes:
#   0 = PASS (zero violations found)
#   1 = FAIL (violations found)
#
# Usage:
#   bash scripts/verify-no-any.sh
#

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$SCRIPT_DIR"

VIOLATIONS=0

echo "========================================="
echo " verify-no-any.sh"
echo " Checking for any type annotations"
echo "========================================="
echo ""

# ------------------------------------------------------------------
# Step 1: Grep for `: any`, `as any`, `any[]` patterns in TS files
# ------------------------------------------------------------------
echo "[1/3] Scanning for any type patterns..."
echo ""

# Use grep to find candidate lines, then filter false positives
# --include patterns cover .ts and .tsx
# --exclude-dir patterns skip generated/vendored directories
CANDIDATES=$(grep -rnE '(: any\b|as any\b|\bany\[\])' \
  --include='*.ts' --include='*.tsx' \
  --exclude-dir='_generated' \
  --exclude-dir='node_modules' \
  --exclude-dir='.next' \
  app/ components/ lib/ convex/ tests/ 2>/dev/null || true)

if [ -n "$CANDIDATES" ]; then
  while IFS= read -r candidate; do
    # Extract just the content after "file:line:"
    content="${candidate#*:*:}"
    trimmed=$(echo "$content" | sed 's/^[[:space:]]*//')

    # Skip comment-only lines
    case "$trimmed" in
      //*|'*'*|\#*) continue ;;
    esac

    # Skip lines where "any" is only part of a camelCase variable name
    # (e.g., anyPdfEvidenceUsed, companyName) -- remove such tokens, then recheck
    cleaned=$(echo "$content" | sed 's/\bany[A-Z][a-zA-Z]*//g')
    if ! echo "$cleaned" | grep -qE '(: any\b|as any\b|\bany\[\])'; then
      continue
    fi

    # Skip lines where "any" appears only inside string literals
    # Remove double-quoted, single-quoted, and backtick strings, then recheck
    without_strings=$(echo "$content" | sed "s/\"[^\"]*\"//g; s/'[^']*'//g")
    without_strings=$(echo "$without_strings" | sed 's/`[^`]*`//g')
    if ! echo "$without_strings" | grep -qE '(: any\b|as any\b|\bany\[\])'; then
      continue
    fi

    # This is a real violation
    echo "  VIOLATION: $candidate"
    VIOLATIONS=$((VIOLATIONS + 1))
  done <<< "$CANDIDATES"
fi

if [ "$VIOLATIONS" -eq 0 ]; then
  echo "  PASS: Zero any type patterns found"
fi

echo ""

# ------------------------------------------------------------------
# Step 2: Grep for angle-bracket <any> patterns (e.g., Validator<any>)
# ------------------------------------------------------------------
echo "[2/3] Scanning for angle-bracket <any> patterns..."
echo ""

ANGLE_CANDIDATES=$(grep -rnE '<any[>,\)]' \
  --include='*.ts' --include='*.tsx' \
  --exclude-dir='_generated' \
  --exclude-dir='node_modules' \
  --exclude-dir='.next' \
  app/ components/ lib/ convex/ tests/ 2>/dev/null || true)

if [ -n "$ANGLE_CANDIDATES" ]; then
  while IFS= read -r candidate; do
    content="${candidate#*:*:}"
    trimmed=$(echo "$content" | sed 's/^[[:space:]]*//')

    # Skip comment-only lines
    case "$trimmed" in
      //*|'*'*|\#*) continue ;;
    esac

    # Skip lines where <any> appears only inside string literals
    without_strings=$(echo "$content" | sed "s/\"[^\"]*\"//g; s/'[^']*'//g")
    without_strings=$(echo "$without_strings" | sed 's/`[^`]*`//g')
    if ! echo "$without_strings" | grep -qE '<any[>,\)]'; then
      continue
    fi

    echo "  VIOLATION: $candidate"
    VIOLATIONS=$((VIOLATIONS + 1))
  done <<< "$ANGLE_CANDIDATES"
fi

if [ "$VIOLATIONS" -eq 0 ]; then
  echo "  PASS: Zero angle-bracket <any> patterns found"
fi

echo ""

# ------------------------------------------------------------------
# Step 3: Run tsc --noEmit
# ------------------------------------------------------------------
echo "[3/3] Running tsc --noEmit..."
echo ""

TSC_OUTPUT=$(npx tsc --noEmit 2>&1 || true)
TSC_ERRORS=$(echo "$TSC_OUTPUT" | grep -c "error TS" || true)

if [ "$TSC_ERRORS" -gt 0 ]; then
  echo "  FAIL: $TSC_ERRORS tsc errors found"
  echo ""
  echo "$TSC_OUTPUT" | grep "error TS" | head -20
  VIOLATIONS=$((VIOLATIONS + TSC_ERRORS))
else
  echo "  PASS: Zero tsc errors"
fi

# ------------------------------------------------------------------
# Summary
# ------------------------------------------------------------------
echo ""
echo "========================================="
if [ "$VIOLATIONS" -eq 0 ]; then
  echo " PASS: Zero any violations found"
  echo "========================================="
  exit 0
else
  echo " FAIL: $VIOLATIONS violation(s) found"
  echo "========================================="
  exit 1
fi
